DROP TABLE IF EXISTS `item_shop`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `item_shop` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `tab_id` int(11) NOT NULL,
  `temp_id` int(11) NOT NULL,
  `is_new` tinyint(1) NOT NULL DEFAULT '1',
  `is_sell` tinyint(1) NOT NULL DEFAULT '1',
  `type_sell` int(11) DEFAULT '1',
  `cost` int(11) DEFAULT '0',
  `icon_spec` int(11) DEFAULT '0',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `item_spec` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tab_id` (`tab_id`) USING BTREE,
  KEY `temp_id` (`temp_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1095 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

