DROP TABLE IF EXISTS `player`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `player` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `account_id` int(11) DEFAULT NULL,
  `name` varchar(20) NOT NULL,
  `head` int(11) NOT NULL DEFAULT '102',
  `gender` int(11) NOT NULL,
  `have_tennis_space_ship` tinyint(1) DEFAULT '0',
  `clan_id_sv1` int(11) NOT NULL DEFAULT '-1',
  `clan_id_sv2` int(11) NOT NULL DEFAULT '-1',
  `data_inventory` text NOT NULL,
  `data_location` text NOT NULL,
  `data_point` text NOT NULL,
  `data_magic_tree` text NOT NULL,
  `items_body` text NOT NULL,
  `items_bag` text NOT NULL,
  `items_box` text NOT NULL,
  `items_box_lucky_round` text NOT NULL,
  `friends` text NOT NULL,
  `enemies` text NOT NULL,
  `data_intrinsic` text NOT NULL,
  `data_item_time` text NOT NULL,
  `data_item_time_sieucap` text NOT NULL,
  `data_task` text NOT NULL,
  `data_mabu_egg` text NOT NULL,
  `data_dua` text NOT NULL,
  `Tai_xiu` text NOT NULL,
  `data_charm` text NOT NULL,
  `skills` text NOT NULL,
  `skills_shortcut` text NOT NULL,
  `pet` text NOT NULL,
  `dao_lu` text NOT NULL,
  `data_black_ball` text NOT NULL,
  `data_side_task` text NOT NULL,
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `violate` bigint(20) NOT NULL,
  `pointPvp` longtext,
  `info_phoban` longtext NOT NULL,
  `info_achievement` longtext NOT NULL,
  `Thu_TrieuHoi` text NOT NULL,
  `nhiemvu_chienthan` text NOT NULL,
  `NguHanhSonPoint` int(11) DEFAULT '0',
  `data_card` text NOT NULL,
  `vndd` int(11) NOT NULL DEFAULT '0',
  `dhieu` varchar(5) NOT NULL DEFAULT '[1,1]',
  `dhtime` varchar(100) NOT NULL DEFAULT '[0,0]',
  `dhtime2` varchar(100) NOT NULL DEFAULT '[0,0]',
  `dhtime3` varchar(100) NOT NULL DEFAULT '[0,0]',
  `dk_tutien` varchar(100) NOT NULL DEFAULT '[0,0,0,0]',
  `Tu_tien` varchar(100) NOT NULL DEFAULT '[0,0,0]',
  `dk_kethon` varchar(100) NOT NULL DEFAULT '[0,0]',
  `ket_hon` varchar(100) NOT NULL DEFAULT '[0,0]',
  `data_lks` text,
  `tien_luc` int(11) DEFAULT '0',
  `tl_dl` float DEFAULT '1',
  `lucky_pool` text,
  `den_bu` tinyint(4) DEFAULT '0',
  `last_time_clan` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `account_id` (`account_id`) USING BTREE,
  CONSTRAINT `player_ibfk_1` FOREIGN KEY (`account_id`) REFERENCES `account` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=240 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
