DROP TABLE IF EXISTS `skill_template`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `skill_template` (
  `nclass_id` int(11) NOT NULL,
  `id` int(11) NOT NULL,
  `NAME` varchar(50) NOT NULL,
  `max_point` smallint(6) NOT NULL DEFAULT '7',
  `mana_use_type` smallint(6) NOT NULL,
  `TYPE` smallint(6) NOT NULL,
  `icon_id` int(11) NOT NULL,
  `dam_info` varchar(255) NOT NULL,
  `slot` int(11) NOT NULL,
  `skills` text NOT NULL,
  PRIMARY KEY (`nclass_id`,`id`) USING BTREE,
  CONSTRAINT `skill_template_ibfk_1` FOREIGN KEY (`nclass_id`) REFERENCES `nclass` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

